function gcd(a, b) {
  while (b !== 0) {
    [a, b] = [b, a % b];
  }
  return a;
}
function lcm(a, b) {
  return a === 0 || b === 0 ? 0 : (a / gcd(a, b)) * b;
}
console.log(gcd(4, 6), lcm(4, 6));

