function deepProperty(obj, path) {
  let current = obj;
  for (const key of path.split(".")) {
    if (current == null || !Object.hasOwn(current, key)) return undefined;
    current = current[key];
  }
  return current;
}
console.log(deepProperty({address:{city:"Dushanbe"}}, "address.city"));

