function categoryStats(products, category) {
  let count = 0, totalPrice = 0;
  for (const product of products) {
    if (product.category !== category) continue;
    count++;
    totalPrice += product.price;
  }
  return {count, totalPrice, avgPrice: count ? totalPrice / count : 0};
}
console.log(categoryStats([{category:"kitchen",price:12},{category:"electronics",price:250}], "kitchen"));

