function longestStreak(dates) {
  const days = [...new Set(dates.map(date => Date.parse(date + "T00:00:00Z")/86400000))].sort((a,b)=>a-b);
  let current = 0, best = 0;
  for (let i=0; i<days.length; i++) {
    current = i>0 && days[i]-days[i-1]===1 ? current+1 : 1;
    best = Math.max(best, current);
  }
  return best;
}
console.log(longestStreak(["2022-12-13","2022-12-10","2022-12-11","2022-12-12","2022-12-21"]));

